import numpy as np

class AnisotropicSectorPhaseLandscape:
    def __init__(self, dim=5):
        """
        Initialize the AnisotropicSectorPhaseLandscape landscape.

        Creates a highly non-homogeneous optimization landscape with:
        - 4 directional sectors based on coordinate dominance
        - 3 concentric regimes per sector using different norm metrics
        - Sharp phase transitions with fundamentally different topology per regime
        """
        self.dim = dim
        self.global_min_value = -100.0  # Deep global minimum
        self.norm_thresholds = [0.5, 2.0, 4.0]  # Phase transition boundaries

    def _get_dominant_sector(self, x):
        """
        Determine which coordinate sector the point belongs to based on
        dominant dimension signs and values.

        Returns sector index (0-3) based on quadrant-like partitioning
        """
        # Use first two dominant dimensions for sector classification
        abs_x = np.abs(x)
        idx_sorted = np.argsort(-abs_x)[:2]  # Top 2 dimensions by magnitude

        if len(idx_sorted) < 2:
            return 0

        d1, d2 = idx_sorted[0], idx_sorted[1]
        s1 = np.sign(x[d1])
        s2 = np.sign(x[d2])

        if s1 >= 0 and s2 >= 0:
            return 0  # Sector 0: positive-positive
        elif s1 >= 0 and s2 < 0:
            return 1  # Sector 1: positive-negative
        elif s1 < 0 and s2 >= 0:
            return 2  # Sector 2: negative-positive
        else:
            return 3  # Sector 3: negative-negative

    def _l1_norm(self, x):
        return np.sum(np.abs(x))

    def _l2_norm(self, x):
        return np.sqrt(np.sum(x**2))

    def _linf_norm(self, x):
        return np.max(np.abs(x))

    def _get_norm_for_sector(self, x, sector):
        """Different sectors use different norm metrics for phase boundaries"""
        if sector % 2 == 0:
            return self._l1_norm(x)
        else:
            return self._linf_norm(x)

    def _smooth_quadratic(self, x, offset=0):
        """Smooth quadratic basin - regime 1"""
        return offset + 0.1 * np.sum(x**2)

    def _coupled_fractal_noise(self, x, sector, frequency_base=1.0):
        """
        Coordinate-coupled fractal noise - regime 2
        Different coupling patterns per sector for non-homogeneity
        """
        noise = 0.0
        n_dims = len(x)

        for i in range(n_dims):
            for j in range(i+1, n_dims):
                if sector == 0:
                    # Sector 0: sin-cos coupling
                    term = np.sin(frequency_base * (x[i] + x[j])) * \
                           np.cos(frequency_base * (x[i] - x[j]))
                elif sector == 1:
                    # Sector 1: phase-shifted coupling
                    term = np.sin(frequency_base * x[i] * x[j]) * \
                           np.cos(frequency_base * (x[i]**2 + x[j]**2))
                elif sector == 2:
                    # Sector 2: high-frequency interaction
                    term = np.sin(3 * frequency_base * x[i]) * \
                           np.cos(2 * frequency_base * x[j])
                else:
                    # Sector 3: non-linear coupling
                    term = np.sin(frequency_base * np.sqrt(x[i]**2 + x[j]**2))

                noise += term * (1.0 / (i + 1))

        return noise

    def _chaotic_barrier(self, x, sector, amplitude=1.0):
        """
        High-frequency chaotic noise - regime 3
        Creates rugged barriers with sector-specific patterns
        """
        chaotic = 0.0

        # High frequency sinusoidal components
        freq_factors = [7, 11, 13, 17, 19]

        for k, freq in enumerate(freq_factors):
            if sector == 0:
                term = np.sin(freq * x[0]) * np.cos(freq * x[-1])
            elif sector == 1:
                term = np.sin(freq * np.sum(x)) * np.cos(freq * np.prod(np.abs(x)))
            elif sector == 2:
                term = np.sin(freq * x[k % len(x)]) * \
                       np.sin(freq * np.sum(x**2))
            else:
                term = np.cos(freq * np.sum(np.abs(x))) * \
                       np.sin(freq * np.max(np.abs(x)))

            chaotic += term * (amplitude / (k + 1))

        return chaotic

    def f(self, x):
        """
        Evaluate the objective function with extreme non-homogeneity.

        Parameters
        ----------
        x : numpy.ndarray
            A real-valued vector of dimension 'dim'.

        Returns
        ------
        float
            The fitness value (to be minimized).
        """
        x = np.asarray(x, dtype=float)

        # Determine sector and norm value
        sector = self._get_dominant_sector(x)
        norm_val = self._get_norm_for_sector(x, sector)

        # Determine which regime based on norm value
        if norm_val < self.norm_thresholds[0]:
            # Regime 1: Inner Smooth Basin (deep global minimum in sector 0)
            if sector == 0:
                # Deepest basin in sector 0
                return self.global_min_value + 0.5 * np.sum(x**2)
            else:
                # Shallow basins in other sectors
                return self.global_min_value + 20 + np.sum(x**2)

        elif norm_val < self.norm_thresholds[1]:
            # Regime 2: Middle Coupled Fractal (moderate complexity)
            base = 50.0 + sector * 10  # Sector-dependent baseline
            distance_penalty = 5.0 * (norm_val - self.norm_thresholds[0])**2
            fractal = self._coupled_fractal_noise(x, sector) * 10.0
            return base + distance_penalty + fractal

        else:
            # Regime 3: Outer Chaotic Barrier (high complexity, high fitness floor)
            base = 100.0 + sector * 20
            distance_penalty = 10.0 * (norm_val - self.norm_thresholds[1])**2
            chaotic = self._chaotic_barrier(x, sector) * 20.0
            return base + distance_penalty + chaotic

    def get_optimum(self):
        """
        Return the known global optimum location and value.

        Returns
        ------
        tuple
            (optimal_point, optimal_value)
        """
        # Optimum is at origin (all zeros) which falls in sector 0
        return (np.zeros(self.dim), self.global_min_value)

    def get_bounds(self):
        """
        Return the search space bounds per dimension.

        Returns
        ------
        tuple
            ((-5.0, 5.0), ) * dim
        """
        return tuple([(-5.0, 5.0) for _ in range(self.dim)])

