class MultiPhaseAnisotropicContrastLandscape:
    def __init__(self, dim):
        """
        Initialize the landscape with multiple phase boundaries and regimes.

        Parameters
        ----------
        dim : int
            Number of dimensions.
        """
        self.dim = dim
        self.regime_boundaries = [0.5, 1.5, 3.0]  # L2-norm boundaries for concentric shells
        self.global_min_value = -1500.0  # Deep global minimum
        self.regime_floors = [500.0, 1500.0, 2500.0]  # Fitness floors for outer regimes

    def _smooth_quadratic(self, x):
        """Smooth quadratic basin for the global regime."""
        return np.sum(x**2)

    def _oscillatory_rastrigin(self, x):
        """Rastrigin-like oscillatory function with multiple local minima."""
        return np.sum(x**2 - 10.0 * np.cos(2.0 * np.pi * x) + 10.0)

    def _anisotropic_cubic(self, x):
        """Cubic anisotropic function with direction-dependent behavior."""
        cubic_term = np.abs(np.sum(np.power(x, 3)))
        anisotropic_term = np.sum(np.abs(x) * np.sin(5.0 * x)**2)
        return cubic_term + anisotropic_term

    def _fractal_noise_like(self, x):
        """High-frequency noise-like function simulating fractal landscape."""
        noise = np.sum(np.sin(10.0 * x) * np.cos(15.0 * x) * np.sin(7.0 * x))
        base = np.sum(np.abs(x) ** 1.5)
        return base + 0.5 * np.abs(noise)

    def f(self, x):
        """
        Evaluate the objective function with multi-phase transitions.

        Parameters
        ----------
        x : numpy.ndarray
            Real-valued vector representing the sample.

        Returns
        -------
        float
            Fitness value (minimization).
        """
        x = np.asarray(x, dtype=float)

        # Calculate L2 norm for regime selection
        r = np.linalg.norm(x)

        # Calculate directional metric for anisotropy
        # Using x[0] as primary directional indicator
        directional_metric = x[0] if len(x) > 0 else 0.0

        # Determine which regime based on concentric boundaries
        if r < self.regime_boundaries[0]:
            # Regime 0: Global Basin (Deep smooth quadratic)
            return self.global_min_value + self._smooth_quadratic(x)
        elif r < self.regime_boundaries[1]:
            # Regime 1: First shell - Oscillatory
            # Different behavior based on direction for non-homogeneity
            if directional_metric > 0:
                return self.regime_floors[0] + 0.8 * self._oscillatory_rastrigin(x)
            else:
                return self.regime_floors[0] + 0.8 * self._fractal_noise_like(x)
        elif r < self.regime_boundaries[2]:
            # Regime 2: Second shell - Anisotropic cubic
            if directional_metric > 0:
                return self.regime_floors[1] + self._anisotropic_cubic(x)
            else:
                return self.regime_floors[1] + 0.9 * self._oscillatory_rastrigin(x)
        else:
            # Regime 3: Outer shell - Fractal with high floor
            # Maximum non-homogeneity with complex behavior
            if directional_metric > 0:
                return self.regime_floors[2] + self._fractal_noise_like(x)
            else:
                return self.regime_floors[2] + self._anisotropic_cubic(x)

import numpy as np

class AnisotropicMultiPhaseLandscape:
    def __init__(self, dim=5):
        """
        Initialize the multi-phase anisotropic landscape.

        Parameters
        ----------
        dim : int
            Number of dimensions.
        """
        self.dim = dim
        self.radial_boundaries = np.array([0.5, 1.5, 3.0, 4.0])  # 5 radial regimes
        self.radial_floor_offset = np.array([0.0, 200.0, 400.0, 600.0, 800.0])
        self.global_min = -1000.0

    def _get_radial_regime(self, x):
        """Determine radial regime based on L2-norm."""
        norm = np.linalg.norm(x)
        for i, boundary in enumerate(self.radial_boundaries):
            if norm <= boundary:
                return i
        return len(self.radial_boundaries)

    def _get_directional_sector(self, x):
        """Determine directional sector based on coordinate signs."""
        signs = np.sign(x)
        # Create unique sector ID from sign pattern
        sector_id = 0
        for i in range(self.dim):
            sector_id += (1 if signs[i] >= 0 else 0) * (2 ** i)
        return sector_id % 8  # 8 directional sectors

    def _norm_based_boundary(self, x, norm_type=2):
        """Calculate different norm-based values for phase transitions."""
        if norm_type == 1:
            return np.sum(np.abs(x))
        elif norm_type == 2:
            return np.sqrt(np.sum(x**2))
        elif norm_type == np.inf:
            return np.max(np.abs(x))
        else:
            return np.sqrt(np.sum(x**2))

    def _regime_quadratic(self, x, regime_idx):
        """Smooth quadratic basin for inner regime."""
        if regime_idx == 0:
            return self.global_min + np.sum(x**2)
        else:
            return self.radial_floor_offset[regime_idx] + 0.5 * np.sum(x**2)

    def _regime_fractal(self, x, regime_idx):
        """Fractal Weierstrass-like function with multi-scale oscillations."""
        w = 0.0
        for scale in [0.5, 1.0, 2.0, 4.0]:
            freq = 2.0 ** scale
            amp = (0.8) ** scale
            for i in range(self.dim):
                w += amp * np.sin(freq * x[i] * (i + 1))
        return self.radial_floor_offset[regime_idx] + 10.0 * np.abs(w)

    def _regime_hyperbolic(self, x, regime_idx):
        """Hyperbolic tangent barriers creating smooth phase transitions."""
        barrier = 0.0
        for i in range(self.dim):
            barrier += 0.5 * (1.0 - np.tanh(np.abs(x[i]) - 1.0))
        return self.radial_floor_offset[regime_idx] + 50.0 * barrier + 20.0 * np.abs(np.sum(x))

    def _regime_interference(self, x, regime_idx):
        """Coordinate-coupled interference patterns."""
        interference = 0.0
        for i in range(self.dim):
            for j in range(i + 1, self.dim):
                interference += np.sin(x[i] * x[j] * 2.0) * np.cos(x[i] + x[j])
        return self.radial_floor_offset[regime_idx] + 15.0 * np.abs(interference)

    def _regime_step(self, x, regime_idx):
        """Discontinuous step-function barriers."""
        steps = 0.0
        for i in range(self.dim):
            steps += int(np.floor(np.abs(x[i]) * 3.0)) % 2
        return self.radial_floor_offset[regime_idx] + 100.0 * steps + 5.0 * np.sum(np.abs(x))

    def _regime_anisotropic(self, x, regime_idx, sector_id):
        """Anisotropic regime with direction-dependent behavior."""
        if sector_id % 2 == 0:
            return self._regime_fractal(x, regime_idx)
        elif sector_id % 3 == 0:
            return self._regime_hyperbolic(x, regime_idx)
        elif sector_id % 4 == 0:
            return self._regime_interference(x, regime_idx)
        else:
            return self._regime_step(x, regime_idx)

    def f(self, x):
        """
        Evaluate the objective function with multi-phase transitions.

        Parameters
        ----------
        x : numpy.ndarray
            Real-valued vector.

        Returns
        ------
        float
            Fitness value (minimization).
        """
        x = np.asarray(x, dtype=float)

        # Get regime information
        radial_regime = self._get_radial_regime(x)
        sector_id = self._get_directional_sector(x)

        # Global minimum basin (innermost regime)
        if radial_regime == 0:
            return self._regime_quadratic(x, radial_regime)

        # Outer regimes with anisotropic behavior based on sector
        return self._regime_anisotropic(x, radial_regime, sector_id)

import numpy as np

class MultiSectorPhaseRegimeLandscape:
    def __init__(self, dim):
        """
        Initialize the Multi-Sector Phase Regime Landscape.

        Parameters
        ----------
        dim : int
            Number of dimensions.
        """
        self.dim = dim
        self.inner_radius = 1.5
        self.mid_radius = 3.5
        self.basin_min = -1000.0
        self.mid_floor = 500.0
        self.outer_floor = 1500.0

    def _rastrigin(self, x):
        return np.sum(x**2 - 10.0 * np.cos(2.0 * np.pi * x))

    def _ackley(self, x):
        # Scaled Ackley for ruggedness
        term1 = -20.0 * np.exp(-0.2 * np.sqrt(np.mean(x**2)))
        term2 = -np.exp(np.mean(np.cos(2.0 * np.pi * x)))
        return 20.0 + np.e + term1 + term2

    def _cubic_anisotropic(self, x):
        return np.sum(np.abs(x)**3) + np.sum(np.sin(10.0 * x)**2)

    def _chaotic_sine(self, x):
        return np.sum(np.sin(5.0 * x)**2 * (1.0 + np.abs(np.sin(3.0 * x))**2))

    def _griewank_like(self, x):
        prod_term = np.prod(np.cos(x / np.sqrt(np.arange(1, self.dim + 1))), axis=0)
        sum_term = np.sum(x**2 / (4000.0 * np.arange(1, self.dim + 1)))
        return sum_term - prod_term + 1.0

    def _quadratic(self, x):
        return np.sum(x**2)

    def f(self, x):
        """
        Evaluate the objective function with multi-regime phase transitions.

        Parameters
        ----------
        x : numpy.ndarray
            Real-valued vector representing the sample.

        Returns
        -----
        float
            Fitness value (minimization).
        """
        x = np.asarray(x, dtype=float)
        # Ensure 1D handling
        if x.ndim > 1:
            x = x.reshape(-1)
        if x.shape[0] != self.dim:
            x = x[:self.dim]

        r = np.linalg.norm(x)

        # --- REGIME 0: Global Basin (Smooth) ---
        # Isolated deep minimum
        if r < self.inner_radius:
            return self._quadratic(x) + self.basin_min

        # Determine Sector (0-3) based on x[0] and x[1] signs
        # Creates 4 directional sectors
        s0 = 1 if x[0] >= 0 else 0
        s1 = 1 if x[1] >= 0 else 0
        sector = s0 + 2 * s1

        # --- REGIME 1: Intermediate Transition ---
        if self.inner_radius <= r < self.mid_radius:
            # Different rugged functions per sector
            if sector == 0:
                val = self._rastrigin(x)
            elif sector == 1:
                val = self._ackley(x)
            elif sector == 2:
                val = self._griewank_like(x)
            else:
                val = self._quadratic(x) * 5.0  # Steep Quadratic

            return self.mid_floor + val

        # --- REGIME 2: Outer Turbulence ---
        else:
            # High floor, more chaotic functions
            if sector == 0:
                val = self._cubic_anisotropic(x)
            elif sector == 1:
                val = self._chaotic_sine(x)
            elif sector == 2:
                val = self._rastrigin(x) * 1.5
            else:
                val = np.sum(np.abs(np.sin(x * 10.0))**2) * 2.0

            return self.outer_floor + val

import numpy as np

class MultiDomainFractalPhaseLandscape:
    def __init__(self, dim=5):
        """
        Initialize the multi-domain fractal phase landscape with extreme non-homogeneity.

        Parameters
        ----------
        dim : int
            Number of dimensions.
        """
        self.dim = dim
        self.global_min = -3000.0
        self.regime_boundaries = np.array([0.5, 2.0, 5.0])
        self.num_angular_sectors = 8

    def _get_radial_regime(self, r):
        """Determine radial regime (0=inner, 1=middle, 2=outer)."""
        if r < self.regime_boundaries[0]:
            return 0
        elif r < self.regime_boundaries[1]:
            return 1
        else:
            return 2

    def _get_angular_sector(self, x):
        """Determine angular sector based on coordinate pattern."""
        # Use coordinate signs and magnitudes to create angular sectors
        sign_pattern = np.sign(x).astype(int)
        # Map sign combinations to sector ID (simplified 8-sector system)
        sector_id = 0
        for i in range(min(self.dim, 3)):
            sector_id = sector_id * 2 + (1 if sign_pattern[i] >= 0 else 0)
        return sector_id % self.num_angular_sectors

    def _coordinate_regime(self, x):
        """Determine coordinate-based regime from absolute values."""
        abs_x = np.abs(x)
        max_dim = np.max(abs_x)
        sum_dim = np.sum(abs_x)

        if max_dim < 0.3 and sum_dim < self.dim * 0.5:
            return "central"
        elif max_dim > 4.0 or sum_dim > self.dim * 3.0:
            return "chaos"
        else:
            return "intermediate"

    def _inner_regime(self, x):
        """Smooth quadratic basin with global minimum."""
        return self.global_min + 150.0 * np.sum(x**2)

    def _middle_quadratic_anisotropic(self, x):
        """Anisotropic quadratic with coordinate-dependent scaling."""
        weights = 1.0 + 5.0 * np.abs(np.sin(3.0 * x))
        return 1500.0 + np.sum(weights * x**2)

    def _middle_fractal_interference(self, x):
        """Fractal interference with coordinate modulation."""
        noise = 0.0
        for i in range(self.dim):
            freq = 15.0 + 5.0 * np.abs(x[i])
            noise += np.sin(freq * x[i]) * np.cos(2*freq * x[i])
        return 2000.0 + 300.0 * np.abs(noise)

    def _middle_oscillatory_barrier(self, x):
        """Oscillatory barriers with amplitude modulation."""
        result = 0.0
        for i in range(self.dim):
            amp = 100.0 + 50.0 * np.abs(x[i])
            freq = 10.0 + np.abs(np.sum(x))
            result += amp * np.sin(freq * x[i] + i * np.pi / self.dim)
        return 1800.0 + np.abs(result)

    def _outer_chaos_regime(self, x):
        """Chaotic regime with high-frequency components."""
        chaos = 0.0
        for i in range(self.dim):
            chaos += np.sin(30.0 * x[i]) * np.cos(45.0 * x[i] + np.sin(60.0 * x[i]))
        return 3500.0 + 500.0 * np.abs(chaos)

    def _outer_fractal_barrier(self, x):
        """Fractal barrier with discontinuous jumps."""
        barrier = 0.0
        for i in range(self.dim):
            # Create discontinuities at specific coordinate values
            discontinuity = 0.0
            for boundary in [1.5, 2.5, 3.5]:
                if np.abs(x[i] - boundary) < 0.1:
                    discontinuity += 200.0
            barrier += np.sin(25.0 * x[i]) * np.cos(35.0 * x[i]) + discontinuity
        return 2500.0 + 400.0 * np.abs(barrier)

    def _outer_polynomial_barriers(self, x):
        """Polynomial barriers with direction-dependent behavior."""
        poly = 0.0
        for i in range(self.dim):
            # Different polynomial behavior per dimension
            poly += np.abs(x[i]**3 - 2.0*x[i] + 0.5*x[i]**4)
        return 3000.0 + 250.0 * poly

    def _regime_function(self, radial_regime, angular_sector, coord_regime, x):
        """Select appropriate function based on regime combination."""
        if radial_regime == 0:
            return self._inner_regime(x)

        if radial_regime == 1:
            sector_type = angular_sector % 3
            if sector_type == 0:
                return self._middle_quadratic_anisotropic(x)
            elif sector_type == 1:
                return self._middle_fractal_interference(x)
            else:
                return self._middle_oscillatory_barrier(x)
        else:  # radial_regime == 2
            sector_type = angular_sector % 3
            if sector_type == 0:
                return self._outer_chaos_regime(x)
            elif sector_type == 1:
                return self._outer_fractal_barrier(x)
            else:
                return self._outer_polynomial_barriers(x)

    def _apply_coord_modulator(self, value, coord_regime):
        """Apply coordinate-based fitness modification."""
        if coord_regime == "central":
            return value - 500.0  # Lower fitness for central region
        elif coord_regime == "chaos":
            return value + 500.0  # Higher fitness for chaos region
        else:
            return value

    def f(self, x):
        """
        Evaluate the multi-domain fractal phase landscape.

        Parameters
        ----------
        x : numpy.ndarray
            Real-valued vector.

        Returns
        -------
        float
            Fitness value (minimization).
        """
        x = np.asarray(x, dtype=float)
        r = np.linalg.norm(x)

        # Determine regime types
        radial_regime = self._get_radial_regime(r)
        angular_sector = self._get_angular_sector(x)
        coord_regime = self._coordinate_regime(x)

        # Get base fitness from regime function
        fitness = self._regime_function(radial_regime, angular_sector, coord_regime, x)

        # Apply coordinate-based modulator for additional non-homogeneity
        fitness = self._apply_coord_modulator(fitness, coord_regime)

        return fitness

