class ExtremeGlobalLocalContrastHPFB:
    def __init__(self, dim):
        """
        Initialize the extreme GlobalLocal contrast landscape with hyperplane partitioning.

        Parameters
        ----------
        dim : int
            Number of dimensions.
        """
        self.dim = dim
        self.global_min_value = -3000.0  # Deep global minimum
        self.fitness_floors = {
            'global': self.global_min_value,
            'smooth': 500.0,
            'oscillatory': 1500.0,
            'fractal': 2500.0,
            'polynomial': 3000.0,
            'chaotic': 4000.0
        }

    def _smooth_convex_basin(self, x):
        """Smooth convex quadratic basin for the global optimum quadrant."""
        return 0.5 * np.sum(x**2)

    def _high_amplitude_oscillatory(self, x):
        """High-amplitude oscillatory function with multiple local minima."""
        oscillation = np.sum(10.0 * np.sin(5.0 * np.pi * x)**2 +
                            8.0 * np.cos(7.0 * np.pi * x)**2)
        return np.sum(x**2) + oscillation

    def _adaptive_fractal_noise(self, x):
        """Adaptive fractal noise with coordinate-dependent scaling."""
        base = np.sum(np.abs(x)**2.5)
        fractal_term = 0.0
        for d in range(len(x)):
            fractal_term += abs(np.sin(15.0 * x[d])) * (abs(x[d]) + 2.0)
        return base + 3.0 * fractal_term

    def _anisotropic_polynomial(self, x):
        """Anisotropic polynomial with mixed-degree terms and high amplitude."""
        term1 = np.sum(np.power(np.abs(x), 4.0))
        term2 = np.sum(np.abs(x) * np.sign(x)**3)
        term3 = np.prod(1.0 + np.abs(x)**3)
        return term1 + 0.8 * term2 + 0.2 * term3

    def _hyperchaotic_noise(self, x):
        """Hyperchaotic noise function with very high amplitude local minima."""
        chaos = 0.0
        for d in range(len(x)):
            chaos += abs(np.sin(25.0 * x[d])) * abs(np.cos(20.0 * x[d]))
        base = np.sum(np.abs(x)**3.0)
        return base + 4.0 * chaos

    def _determine_regime(self, x):
        """
        Determine which regime a point belongs to based on coordinate signs.
        Returns a tuple of (regime_id, regime_type)
        """
        signs = np.sign(x)
        neg_count = np.sum(signs < 0)
        pos_count = np.sum(signs > 0)
        zero_count = np.sum(signs == 0)

        # Global minimum regime: all coordinates negative
        if neg_count == self.dim and pos_count == 0 and zero_count == 0:
            return 'global', 'global'

        # Smooth regime: mostly negative with few positive
        elif neg_count >= pos_count + 2:
            return 'smooth', 'smooth'

        # Oscillatory regime: mostly positive
        elif pos_count >= neg_count + 2:
            return 'oscillatory', 'oscillatory'

        # Fractal regime: balanced negative/positive
        elif abs(neg_count - pos_count) <= 1:
            return 'fractal', 'fractal'

        # Polynomial regime: mixed with more positive
        elif pos_count > neg_count:
            return 'polynomial', 'polynomial'

        # Chaotic regime: mixed with more negative
        else:
            return 'chaotic', 'chaotic'

    def f(self, x):
        """
        Evaluate the objective function with extreme GlobalLocal contrast.

        Parameters
        ----------
        x : numpy.ndarray
            Real-valued vector representing the sample.

        Returns
        -------
        float
