        """
        x = np.asarray(x, dtype=float)
        regime, regime_type = self._determine_regime(x)

        # Apply distance-dependent scaling to increase GlobalLocal contrast
        r = np.linalg.norm(x)
        distance_factor = 1.0 + 0.5 * r

        # Global minimum regime - deep smooth basin
        if regime == 'global':
            return self.global_min_value + self._smooth_convex_basin(x)

        # Other regimes with exponentially increasing fitness floors
        elif regime == 'smooth':
            return self.fitness_floors['smooth'] * distance_factor + self._smooth_convex_basin(x)

        elif regime == 'oscillatory':
            return self.fitness_floors['oscillatory'] * distance_factor + self._high_amplitude_oscillatory(x)

        elif regime == 'fractal':
            return self.fitness_floors['fractal'] * distance_factor + self._adaptive_fractal_noise(x)

        elif regime == 'polynomial':
            return self.fitness_floors['polynomial'] * distance_factor + self._anisotropic_polynomial(x)

        elif regime == 'chaotic':
            return self.fitness_floors['chaotic'] * distance_factor + self._hyperchaotic_noise(x)

        # Fallback (should not reach here)
        return 5000.0 + np.sum(x**2)

import numpy as np

class HyperRegimeDiscontinuityLandscape:
    def __init__(self, dim=5):
        """
        Initialize the HyperRegimeDiscontinuityLandscape.

        Parameters
        ----------
        dim : int
            Number of dimensions.
        """
        self.dim = dim
        self.global_radius = 0.15
        self.regime1_radius = 1.0
        self.regime2_radius = 2.5
        self.regime3_radius = 4.0

        # Fitness values for extreme GlobalLocal contrast
        self.global_min = -100000.0
        self.regime1_floor = 50000.0
        self.regime2_floor = 75000.0
        self.regime3_floor = 100000.0
        self.regime4_floor = 125000.0

        # Regime-specific parameters for non-homogeneity
        self.base_freq = 25.0
        self.fractal_scale = 10.0
        self.discontinuity_penalty = 25000.0

    def _get_regime_index(self, x):
        """Determine regime based on L-infinity norm with sharp boundaries."""
        l_inf = np.max(np.abs(x))
        if l_inf < self.global_radius:
            return 0
        elif l_inf < self.regime1_radius:
            return 1
        elif l_inf < self.regime2_radius:
            return 2
        elif l_inf < self.regime3_radius:
            return 3
        else:
            return 4

    def _get_sector_code(self, x):
        """Get coordinate sign sector code for 2^dim partitioning."""
        sector_code = 0
        for i in range(self.dim):
            if x[i] > 0:
                sector_code += 2**i
        return sector_code

    def _angular_complexity(self, x):
        """Compute angle-dependent complexity factor."""
        angles = np.arctan2(x[1%self.dim], x[0]) if self.dim >= 2 else 0.0
        if self.dim > 2:
            for i in range(2, min(self.dim, 5)):
                angles += np.arctan2(x[i], x[i-1])
        return 1.0 + 0.3 * np.abs(np.sin(angles * 5.0))

    def _regime_discontinuity_penalty(self, x, current_regime):
        """Add penalty at regime boundaries for phase transitions."""
        l_inf = np.max(np.abs(x))
        thresholds = [self.global_radius, self.regime1_radius, 
                     self.regime2_radius, self.regime3_radius]

        penalty = 0.0
        if current_regime > 0:
            dist_to_boundary = abs(l_inf - thresholds[current_regime - 1])
            if dist_to_boundary < 0.05:
                penalty = self.discontinuity_penalty * (1.0 - dist_to_boundary / 0.05) ** 2
        return penalty

    def _polynomial_regime(self, x, degree, scale):
        """Polynomial-based regime with sector-dependent coefficients."""
        sector_code = self._get_sector_code(x)
        angular_factor = self._angular_complexity(x)

        result = 0.0
        for i in range(self.dim):
            coef = (1.0 + 0.1 * sector_code) * (1.0 + 0.2 * angular_factor)
            result += coef * np.abs(x[i]) ** degree
        return result

    def _oscillatory_regime(self, x, base_freq, complexity):
        """High-frequency oscillatory regime with adaptive parameters."""
        sector_code = self._get_sector_code(x)
        angular_factor = self._angular_complexity(x)

        result = 0.0
        for i in range(self.dim):
            freq = base_freq * (1.0 + 0.15 * i) * (1.0 + 0.1 * sector_code)
            phase = i * np.pi / 4 + sector_code * 0.3
            result += np.sin(freq * x[i] * angular_factor + phase) ** 2
        return result

    def _fractal_noise_regime(self, x, scale, iterations):
        """Fractal noise regime with quantum-inspired superposition."""
        noise = 0.0
        for i in range(self.dim):
            for k in range(1, iterations + 1):
                freq = scale * k * (1.0 + 0.1 * i)
                noise += np.abs(np.sin(freq * x[i])) ** (2.0 + 0.5 * (i % 3))
        return noise

    def _chaotic_polynomial_regime(self, x, scale):
        """Chaotic polynomial regime with coordinate coupling."""
        result = 0.0
        for i in range(self.dim):
            for j in range(i + 1, self.dim):
                coupling = np.abs(x[i] * x[j]) * scale
                result += coupling ** 2 + np.sin(coupling * 10.0) ** 4
        return result

    def _global_basin(self, x):
        """Deep smooth quadratic basin with global minimum."""
        return self.global_min + 50000.0 * np.sum(x ** 2)

    def _regime1(self, x):
        """Regime 1: Low-degree polynomial with sector partitioning."""
        degree = 3 + (self._get_sector_code(x) % 3)
        return self.regime1_floor + 1500.0 * self._polynomial_regime(x, degree, 2.0)

    def _regime2(self, x):
        """Regime 2: High-frequency oscillatory with angular modulation."""
        complexity = 2 + (self._get_sector_code(x) % 4)
        freq = self.base_freq * (1.0 + 0.2 * complexity)
        return self.regime2_floor + 2000.0 * self._oscillatory_regime(x, freq, complexity)

    def _regime3(self, x):
        """Regime 3: Fractal noise with quantum superposition."""
        iterations = 3 + (self._get_sector_code(x) % 3)
        return self.regime3_floor + 2500.0 * self._fractal_noise_regime(x, self.fractal_scale, iterations)

    def _regime4(self, x):
        """Regime 4: Chaotic polynomial with coordinate coupling."""
        scale = 5.0 * (1.0 + 0.1 * self._get_sector_code(x))
        return self.regime4_floor + 3000.0 * self._chaotic_polynomial_regime(x, scale)

    def f(self, x):
        """
        Evaluate the HyperRegimeDiscontinuityLandscape.

        Parameters
        ----------
        x : numpy.ndarray
            Real-valued vector.

        Returns
        -------
        float
            Fitness value (minimization).
        """
        x = np.asarray(x, dtype=float)

        # Ensure input is within bounds
        if not np.all((-5.0 <= x) & (x <= 5.0)):
            return 200000.0  # Penalty for out-of-bounds

        regime = self._get_regime_index(x)
        discontinuity_penalty = self._regime_discontinuity_penalty(x, regime)

        if regime == 0:
            base_fitness = self._global_basin(x)
        elif regime == 1:
            base_fitness = self._regime1(x)
        elif regime == 2:
            base_fitness = self._regime2(x)
        elif regime == 3:
            base_fitness = self._regime3(x)
        else:
            base_fitness = self._regime4(x)

        return base_fitness + discontinuity_penalty
